import os
import re
import json

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

    G = {}
    # Parse demo inputs and outputs
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    m = re.search(pattern, t)
    if not m:
        return G

    current_key = None
    current_rows = []

    for idx, match in enumerate(re.finditer(pattern, t)):
        label = match.group(1)
        h, w = int(match.group(2)), int(match.group(3))

        if label == 'Test input':
            current_key = 'Test input'
        else:
            pair_num = int(label.split()[2])
            if pair_num == 1:
                current_key = f'demo_1_input'
            elif pair_num == 1:
                current_key = f'demo_1_output'

        # Extract the next h rows
        if idx < len(re.findall(pattern, t)) + 1:
            text_after = t[m.end():].split('\n')[0:h] if h <= len(t[m.end():].split('\n')) else t[m.end():].split('\n')[:h]
            for row_text in text_after:
                if row_text.strip():
                    current_rows.append([int(x) for x in row_text.split()])

    # Find Test input and parse properly
    sections = re.split(r'\n\s*\n', t)
    for section in sections:
        if 'Test input' in section:
            match = re.search(r'Test input \((\d+)x(\d+)\):', section)
            if match:
                h, w = int(match.group(1)), int(match.group(2))
                rows = [[int(x) for x in line.split()] for line in section.split('\n')[match.end():match.end()+h] if line.strip() and not line.startswith('Wrong')]
                G['Test input'] = rows
                print(f"Found Test input: {len(rows)}x{len(rows[0]) if rows else 0}")
                break

    return G

G = load()
print("Loaded grids:", list(G.keys()))
if 'Test input' in G:
    print("\nTest input:")
    for row in G['Test input']:
        print(row)

